// UnmarshalJSON accepts both legacy string ports and the structured format
// written by earlier versions of this package.
func (p *AffectedProcess) UnmarshalJSON(data []byte) error {
	type affectedProcessJSON struct {
		PID             string            `json:"pid,omitempty"`
		Name            string            `json:"name,omitempty"`
		ListenPorts     []json.RawMessage `json:"listenPorts,omitempty"`
		ListenPortStats []PortStat        `json:"listenPortStats,omitempty"`
	}
	var raw affectedProcessJSON
	if err := json.Unmarshal(data, &raw); err != nil {
		return err
	}
	p.PID = raw.PID
	p.Name = raw.Name
	p.ListenPorts = nil
	p.ListenPortStats = raw.ListenPortStats
	for _, item := range raw.ListenPorts {
		var legacy string
		if err := json.Unmarshal(item, &legacy); err == nil {
			p.ListenPorts = append(p.ListenPorts, legacy)
			continue
		}

		var structured struct {
			Address           string   `json:"address"`
			BindAddress       string   `json:"bindAddress"`
			Port              string   `json:"port"`
			PortScanSuccessOn []string `json:"portScanSuccessOn"`
			PortReachableTo   []string `json:"portReachableTo"`
		}
		if err := json.Unmarshal(item, &structured); err != nil {
			return err
		}
		address := structured.BindAddress
		if address == "" {
			address = structured.Address
		}
		if strings.HasPrefix(address, "[") && strings.HasSuffix(address, "]") {
			address = strings.TrimSuffix(strings.TrimPrefix(address, "["), "]")
		}
		reachableTo := structured.PortReachableTo
		if reachableTo == nil {
			reachableTo = structured.PortScanSuccessOn
		}
		if address != "" || structured.Port != "" {
			p.ListenPortStats = append(p.ListenPortStats, PortStat{
				BindAddress:     address,
				Port:            structured.Port,
				PortReachableTo: reachableTo,
			})
			p.ListenPorts = append(p.ListenPorts, net.JoinHostPort(address, structured.Port))
		}
	}
	return nil
}

// PortStat is the parsed address, port, and reachability information for a listener.
type PortStat struct {
	BindAddress     string   `json:"bindAddress"`
	Port            string   `json:"port"`
	PortReachableTo []string `json:"portReachableTo,omitempty"`
}

// NewPortStat parses an IP address and port in host:port form.
func NewPortStat(ipPort string) (*PortStat, error) {
	stat := &PortStat{}
	if ipPort == "" {
		return stat, nil
	}

	address, port, err := net.SplitHostPort(ipPort)
	if err != nil {
		return stat, fmt.Errorf("invalid ip:port %q: %w", ipPort, err)
	}
	if address != "*" && net.ParseIP(address) == nil {
		return stat, fmt.Errorf("invalid IP address %q", address)
	}
	portNumber, err := strconv.ParseUint(port, 10, 16)
	if err != nil || 65535 < portNumber {
		return stat, fmt.Errorf("invalid port %q", port)
	}
	stat.BindAddress = address
	stat.Port = port
	return stat, nil
}

// FindPortReachableTo returns the IPs whose open port matches this listener.
func (p PortStat) FindPortReachableTo(ipPorts []string) []string {
	if p.BindAddress == "" || p.Port == "" {
		return []string{}
	}
	addresses := []string{}
	for _, ipPort := range ipPorts {
		candidate, err := NewPortStat(ipPort)
		if err != nil || candidate.Port != p.Port {
			continue
		}
		if p.BindAddress == "*" || p.BindAddress == candidate.BindAddress {
			addresses = append(addresses, candidate.BindAddress)
		}
	}
	return addresses
}

// HasReachablePort reports whether a process associated with this package has
// a listener reachable through at least one scanned address.
func (p Package) HasReachablePort() bool {
	for _, ap := range p.AffectedProcs {
		for _, lp := range ap.ListenPortStats {
			if len(lp.PortReachableTo) > 0 {
				return true
			}
		}
	}

	return false
}

// HasPortScanSuccessOn is kept for compatibility with callers using the old name.
func (p Package) HasPortScanSuccessOn() bool {
	return p.HasReachablePort()
}

