			PID:             pid,
			Name:            procName,
			ListenPorts:     pidListenPorts[pid],
			ListenPortStats: pidListenPortStats[pid],
		}

		for _, n := range pkgNames {
			p, ok := o.Packages[n]
			if !ok {
